fn initialize_inductive(post: Self, backing_cells: Seq<CellId>, storage: Map<nat, cell::PointsTo<T>>) {
    broadcast use group_vstd_default;
    assert(post.backing_cells == backing_cells);
    assert(post.storage == storage);
    assert(post.len() == backing_cells.len());
    // Prove valid_storage_all by proving valid_storage_at_idx for all i
    assert(forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i)) by {
        assert(post.backing_cells == backing_cells);
        assert(post.storage == storage);
        assert(post.len() == backing_cells.len());
        assert(post.head == 0);
        assert(post.tail == 0);
        assert(post.producer == ProducerState::Idle(0));
        assert(post.consumer == ConsumerState::Idle(0));
        // From the transition precondition
        assert(forall|i: nat| 0 <= i && i < backing_cells.len() ==> storage.dom().contains(i) && storage.index(i).id() == backing_cells.index(i as int) && storage.index(i).is_uninit());
        // For any i where 0 <= i < post.len():
        assert forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i) by {
            // Since post.len() = backing_cells.len()
            assert(0 <= i && i < backing_cells.len());
            // From precondition
            assert(storage.dom().contains(i));
            assert(storage.index(i).id() == backing_cells.index(i as int));
            assert(storage.index(i).is_uninit());
            // Convert to post state
            assert(post.storage.dom().contains(i));
            assert(post.storage.index(i).id() == post.backing_cells.index(i as int));
            assert(post.storage.index(i).is_uninit());
            // Check is_checked_out
            assert(post.producer.is_Idle() && post.consumer.is_Idle());
            // is_checked_out = false
            assert(!post.is_checked_out(i));
            // Check in_active_range
            assert(post.head == 0 && post.tail == 0);
            // in_active_range = false
            assert(!post.in_active_range(i));
            // So valid_storage_at_idx = true
            assert(post.valid_storage_at_idx(i));
        }
    }
}

